package com.campusiq.auth.service; import com.campusiq.auth.dto.*; import com.campusiq.auth.security.JwtService; import com.campusiq.common.exception.ApiException; import com.campusiq.user.dto.UserResponse; import com.campusiq.user.entity.User; import com.campusiq.user.repository.UserRepository; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public AuthResponse register(RegisterRequest r){if(users.existsByEmail(r.email().toLowerCase()))throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");User u=new User();u.setName(r.name());u.setEmail(r.email());u.setPasswordHash(encoder.encode(r.password()));users.save(u);return response(u);} public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return response(u);} private AuthResponse response(User u){return new AuthResponse(jwt.createToken(u.getId(),u.getEmail()),UserResponse.from(u));}}
